using System.Buffers.Binary;
using System.Diagnostics;
using System.Text;
using System.Text.Json;
namespace DiskLens;
public static class ScanReliabilityTests {
 public static int PartialWorker(){using var output=Console.OpenStandardOutput();void Send(params ScanEntry[] entries){using var payload=new MemoryStream();using(var writer=new BinaryWriter(payload,Encoding.UTF8,true)){writer.Write((ushort)entries.Length);foreach(var e in entries){writer.Write(e.Kind);writer.Write(e.Path);writer.Write(e.Size);writer.Write(e.Modified);if(e.Kind==2)writer.Write(e.Detail);}}Span<byte> header=stackalloc byte[4];BinaryPrimitives.WriteInt32LittleEndian(header,(int)payload.Length);output.Write(header);output.Write(payload.GetBuffer(),0,(int)payload.Length);output.Flush();}var root=JsonSerializer.Deserialize<string>(Console.ReadLine()!)!;Send(new ScanEntry(1,System.IO.Path.Combine(root,"slow"),0,0),new ScanEntry(0,System.IO.Path.Combine(root,"root.bin"),4,DateTime.UtcNow.Ticks));output.Write(new byte[4]);output.Flush();var child=JsonSerializer.Deserialize<string>(Console.ReadLine()!)!;Send(new ScanEntry(0,System.IO.Path.Combine(child,"partial.bin"),7,DateTime.UtcNow.Ticks));Thread.Sleep(60000);return 0;}
 sealed class InlineProgress(Action<string> report):IProgress<string>{public void Report(string value)=>report(value);}
 public static async Task Run(string root,Action<bool,string> check){
  var fixture=System.IO.Path.Combine(root,"wire-fixture");Directory.CreateDirectory(fixture);const int count=513;for(int i=0;i<count;i++)File.WriteAllText(System.IO.Path.Combine(fixture,$"quote's-测试-{i:D4}.bin"),"123");Directory.CreateDirectory(System.IO.Path.Combine(fixture,"excluded"));File.WriteAllText(System.IO.Path.Combine(fixture,"excluded","hidden.txt"),"skip");var store=new Store(System.IO.Path.Combine(root,"wire-store"));var pending=System.IO.Path.Combine(store.Home,"batched.pending");var scan=await new Scanner().Run(fixture,pending,false,"*excluded*",new InlineProgress(_=>{}),CancellationToken.None);store.Commit(scan,pending,20);check(scan.Files==count&&scan.Bytes==count*3,"multiple binary batches, partial last batch, Unicode and apostrophe paths");check(store.Map(scan,fixture).Sum(e=>e.Size)==scan.Bytes,"prepared statements preserve folder aggregates");check(store.Search(scan,"quote's-测试-000?.bin",0,0,"All files").Count==10,"compiled wildcard matching preserves Unicode/name semantics");
  Process Fault()=>NativeWorkers.Start("--test-partial-worker");var fault=new Scanner(1500,Fault);pending=System.IO.Path.Combine(store.Home,"partial.pending");var partial=await fault.Run(fixture,pending,false,"",new InlineProgress(_=>{}),CancellationToken.None);store.Commit(partial,pending,20);check(partial.Files==2&&partial.Bytes==11&&partial.Issues==1&&store.Map(partial,fixture).Sum(e=>e.Size)==11,"child timeout retains received batch, records issue and finalizes consistently");
  using var cancellation=new CancellationTokenSource();bool started=false;int workerId=0;Process CancelWorker(){var process=Fault();started=true;workerId=process.Id;cancellation.CancelAfter(300);return process;}var timer=Stopwatch.StartNew();try{await new Scanner(10000,CancelWorker).Run(fixture,System.IO.Path.Combine(store.Home,"mid-cancel.pending"),false,"",new InlineProgress(_=>{}),cancellation.Token);throw new Exception("Mid-scan cancellation failed");}catch(OperationCanceledException){check(started&&timer.Elapsed<TimeSpan.FromSeconds(8)&&store.History().Count==2,"mid-scan cancellation while worker blocked preserves published snapshots");}
  await Task.Delay(100);bool exited;try{using var process=Process.GetProcessById(workerId);exited=process.HasExited;}catch(ArgumentException){exited=true;}check(exited,"cancelled filesystem worker terminated");
  using var cancelled=new CancellationTokenSource();cancelled.Cancel();try{store.Search(scan,"absent",0,0,"All files",ct:cancelled.Token);throw new Exception("Search cancellation failed");}catch(OperationCanceledException){check(true,"search query supports cancellation");}
  using(var db=new Db(store.PathFor(scan))){using var insert=db.Prepare("INSERT INTO files VALUES(?1,?2,?3,?4,?5)");foreach(var name in new[]{"report[1].PDF","plain.txt","quote's.bin","Kelvin-K.txt","مرحبا.txt"}){insert.Text(1,System.IO.Path.Combine(fixture,name));insert.Text(2,fixture);insert.Number(3,9);insert.Number(4,DateTime.UtcNow.Ticks);insert.Text(5,System.IO.Path.GetExtension(name).ToLowerInvariant());insert.Execute();}}
  var rootPath=System.IO.Path.GetPathRoot(fixture)!;using(var db=new Db(store.PathFor(scan)))db.Exec($"INSERT INTO files VALUES({Db.Q(System.IO.Path.Combine(rootPath,"root-report.pdf"))},{Db.Q(rootPath)},9,0,'.pdf')");var all=store.All(scan).ToArray();foreach(var pattern in new[]{"root-report.?df","report[?].pdf","quote's.bin","KELVIN-k","مرحبا","plain;*.PDF","*.bin",fixture+"\\plain.txt","absent","*测试*;plain","*report[1]*"}){var expected=all.Where(e=>Rules.Match(e.Path,pattern)).Select(e=>e.Path).ToHashSet(StringComparer.OrdinalIgnoreCase);var actual=store.Search(scan,pattern,0,0,"All files").Select(e=>e.Path).ToHashSet(StringComparer.OrdinalIgnoreCase);check(actual.Count==Math.Min(500,expected.Count)&&actual.IsSubsetOf(expected),"SQL search candidate filtering preserves "+pattern);}
  var malformed=new MemoryStream();malformed.Write(BitConverter.GetBytes(ScanWire.MaxBytes+1));malformed.Position=0;try{await ScanWire.Read(malformed,CancellationToken.None);throw new Exception("Unbounded worker frame accepted");}catch(IOException){check(true,"oversized worker frame rejected before allocation");}
 }
}

